// One row per bookmaker back price, beside the lowest exchange lay for the same outcome.
// rating = back / lay x 100. With commission c (a fraction), the rating after commission is
// back x (1 - c) / (lay - c) x 100, the same figure when c is 0.
const c = Number($('Settings').first().json.commissionPercent) / 100;
const round = (x) => Math.round(x * 100) / 100;
const checkedAt = DateTime.now().setZone('Europe/London').toFormat('yyyy-MM-dd HH:mm');
const rows = [];

for (const [index, item] of $input.all().entries()) {
  const ev = item.json;
  const event = ev.home_team && ev.away_team ? `${ev.home_team} v ${ev.away_team}` : (ev.event_name ?? ev.event_id);
  const kickOff = ev.commence_time
    ? DateTime.fromISO(ev.commence_time).setZone('Europe/London').toFormat('ccc d LLL HH:mm')
    : '';
  for (const market of ev.markets ?? []) {
    for (const outcome of market.outcomes ?? []) {
      const lays = Array.isArray(outcome.lay) ? outcome.lay.filter((l) => l.price > 1) : [];
      if (!lays.length) continue;
      const lay = lays.reduce((best, l) => (l.price < best.price ? l : best));
      for (const back of outcome.back ?? []) {
        if (!(back.price > 1)) continue;
        rows.push({
          json: {
            checked_at: checkedAt,
            kick_off: kickOff,
            competition: ev.sport_title,
            event,
            market: market.key,
            outcome: outcome.point == null ? outcome.name : `${outcome.name} ${outcome.point}`,
            bookmaker: back.bookmaker,
            back: back.price,
            exchange: lay.exchange,
            lay: lay.price,
            lay_available: lay.available ?? 0,
            rating: round((back.price / lay.price) * 100),
            rating_after_commission: round(((back.price * (1 - c)) / (lay.price - c)) * 100),
            back_link: back.link,
            lay_link: lay.link,
            event_id: ev.event_id,
          },
          pairedItem: { item: index },
        });
      }
    }
  }
}

return rows;
